                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_13271_2" id="ielts_listening_answer_13271_2_0" value="A"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_13271_2" id="ielts_listening_answer_13271_2_1" value="B"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_13271_2" id="ielts_listening_answer_13271_2_2" value="C"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_13271_2" id="ielts_listening_answer_13271_2_3" value="D"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_13271_2" id="ielts_listening_answer_13271_2_4" value="E"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_13271_2" id="ielts_listening_answer_13271_2_5" value="F"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_13271_2" id="ielts_listening_answer_13271_2_6" value="G"></td>                                                                                                            <td class="ielts