                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_13271_3" id="ielts_listening_answer_13271_3_0" value="A"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_13271_3" id="ielts_listening_answer_13271_3_1" value="B"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_13271_3" id="ielts_listening_answer_13271_3_2" value="C"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_13271_3" id="ielts_listening_answer_13271_3_3" value="D"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_13271_3" id="ielts_listening_answer_13271_3_4" value="E"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_13271_3" id="ielts_listening_answer_13271_3_5" value="F"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_13271_3" id="ielts_listening_answer_13271_3_6" value="G"></td>                                                                                                            <td class="ielts